#include <stddef.h>
int count_over_threshold(const int *samples, int n, int threshold, int *first_index)
{
    int count = 0;

    if (first_index != NULL) {
        *first_index = -1;
    }
    if (samples == NULL || n <= 0) {
        return 0;
    }

    for (int i = 0; i < n; i++) {
        if (samples[i] > threshold) {
            if (count == 0 && first_index != NULL) {
                *first_index = i;
            }
            count++;
        }
    }
    return count;
}
